public class LockerCodeManagement { static class Locker { private String code; private final int lockerNumber; Locker(int lockerNumber,String code){this.lockerNumber=lockerNumber;this.code=code;} boolean changeCode(String current,String next){if(code.equals(current)){code=next;return true;}return false;} } public static void main(String[]args){Locker locker=new Locker(101,"1234");System.out.println("Changed: "+locker.changeCode("1234","5678"));System.out.println("Changed: "+locker.changeCode("0000","9999"));} }
